/* Resolution-independent illustrated props, drawn to match the room's ink outlines. */
window.LabStoryArt={
 bottle(label='07',small=false,detail=false){return `<svg viewBox="0 0 180 300" aria-hidden="true" class="bottle-art"><ellipse cx="91" cy="282" rx="62" ry="10" fill="#263b4720"/><g stroke="#384953" stroke-width="1.8" stroke-linejoin="round"><path d="M56 63v17C37 90 31 103 31 123v137q58 26 118 0V123c0-20-8-35-24-43V63Z" fill="#bb8135"/><path d="M40 121q51 14 99 0v132q-48 20-99 0Z" fill="#a46c2d" stroke="none"/><path d="M39 118q3-23 21-30v65l-16-4v109l-7-3Z" fill="#e3ae59" stroke="none"/><path d="M125 89q15 16 16 37v130l-10 4V113Z" fill="#785027" opacity=".45" stroke="none"/><path d="M49 129v18m0 94v14" stroke="#f7d089" stroke-width="4"/><ellipse cx="90" cy="65" rx="34" ry="6" fill="#59452c"/><g class="bottle-cap"><path d="M53 31q38-12 75 0v35q-38 17-75 0Z" fill="#b94d42"/><ellipse cx="90" cy="31" rx="37.5" ry="10" fill="#d16c55"/><path d="M61 38v24m12-21v25m12-23v25m12-25v25m12-27v26m11-29v25" stroke="#873e35" stroke-width="1.5"/></g><path d="M31 157q57 18 118 0v82q-58 21-118 0Z" fill="#f8efd6"/><path d="M33 159v78q7 4 13 5v-80Z" fill="#e2d6b6" opacity=".65" stroke="none"/><path d="M138 161v80l9-3v-79Z" fill="#cbbd97" opacity=".28" stroke="none"/><g class="bottle-print" fill="#304854" stroke="none" text-anchor="middle" transform="matrix(1,-.025,.015,1,-3,3)"><text x="90" y="175" font-size="7" letter-spacing="1.1">${small?'ПОРЦИЯ':'ПРОБА'}</text><text x="90" y="216" font-size="${small?23:26}" font-weight="800" letter-spacing=".6">${label}</text>${detail?'<text x="90" y="235" font-size="6.7">T-02 · P-214 · 12:30</text>':''}</g></g></svg>`;},
 lidFrame(angle){const a=angle*Math.PI/180,dx=45*Math.cos(a),dy=65*Math.cos(a)-125*Math.sin(a),A=[130,194],B=[250,176],C=[250+dx,176+dy],D=[130+dx,194+dy];const poly=points=>'M'+points.map(p=>p.join(' ')).join(' L')+' Z';const inset=([u,v])=>[A[0]+(B[0]-A[0])*u+dx*v,A[1]+(B[1]-A[1])*u+dy*v];return {outer:poly([A,B,C,D]),inner:poly([[.09,.14],[.91,.14],[.91,.87],[.09,.87]].map(inset)),rim:poly([A,B,[B[0],B[1]+7],[A[0],A[1]+7]])};},
 device(value='—',closed=false,liquid=false){const lid=this.lidFrame(closed?0:82);return `<svg viewBox="0 0 610 420" class="device-art" aria-hidden="true"><ellipse cx="310" cy="378" rx="235" ry="24" fill="#34485115"/><g stroke="#354954" stroke-width="2" stroke-linejoin="round"><path d="m75 203 323-49 133 126-12 78-307 37-143-100Z" fill="#b7c3c2"/><path d="m75 203 323-49 133 126-319 47Z" fill="#f6f0df"/><path d="m212 327 319-47-12 78-307 37Z" fill="#91a4a8"/><path d="m75 203 137 124v68L69 295Z" fill="#d5d9ce"/><path d="m90 285 112 93m22-37 281-34" fill="none" stroke="#eef1e5" stroke-width="2"/><path d="m236 364 52-6m-51 13 52-6m-51 13 52-6" stroke="#526c77" stroke-width="2"/><path d="m101 321 19 16v13l-19-16m329 38 27-3v10l-27 4" fill="#344d5e"/><circle cx="482" cy="334" r="3" fill="#dde1d4"/><path d="m255 253 159-24 55 45-164 25Z" fill="#344d5e"/><path d="m270 256 139-20 39 33-139 21Z" fill="#d7e6df" stroke-width="1.5"/><text class="meter-reading" x="351" y="267" transform="rotate(-8 357 267)" text-anchor="middle" font-family="Manrope,sans-serif" font-size="27" font-weight="800" stroke="none" fill="#263e4c">${value}</text><text x="412" y="262" font-size="9" transform="rotate(-8 412 262)" fill="#45616a" stroke="none">°Bx</text><path d="m340 308 37-6 14 13-38 6Z" fill="#ba4b42"/><path d="m399 300 37-6 14 13-38 6Z" fill="#55727b"/><path d="m353 309 16-2m42-1 13-2" stroke="#f4eedf" stroke-width="1.5"/><ellipse cx="210" cy="218" rx="65" ry="30" fill="#9eafb1"/><ellipse cx="210" cy="218" rx="40" ry="18" fill="#dce1d8"/><ellipse cx="210" cy="218" rx="19" ry="9" fill="${liquid?'#d79b3e':'#647e87'}"/>
 <g class="meter-lid ${closed?'closed':''}"><path class="lid-face" d="${lid.outer}" fill="#617b87"/><path class="lid-inset" d="${lid.inner}" fill="#385463"/><path class="lid-rim" d="${lid.rim}" fill="#859ca3"/></g></g></svg>`;},
 pipette(){return `<svg viewBox="0 0 100 300" aria-hidden="true"><g stroke="#354954" stroke-width="1.7" stroke-linejoin="round"><rect x="39" y="5" width="24" height="26" rx="7" fill="#bd4a43"/><path d="M30 29h43l-6 124-25 1Z" fill="#f2efe1"/><path d="m43 153 23-1-8 88-9 1Z" fill="#9bb1b7"/><path d="m49 241 9-1-5 46Z" fill="#e1e9e2"/><path d="m46 51 13 1-2 44H45Z" fill="#718b96"/></g></svg>`;},
 beaker(filled=true,label='07'){return `<svg viewBox="0 0 180 220" aria-hidden="true"><ellipse cx="90" cy="203" rx="65" ry="10" fill="#34485116"/><g stroke="#435965" stroke-width="1.7" stroke-linejoin="round"><path d="M30 30h117l-5 152q-52 24-104 0Z" fill="#e8eee6" fill-opacity=".7"/><path class="beaker-liquid" d="M36 100q55 17 109 0l-3 82q-52 24-104 0Z" fill="${filled?'#d9ac58':'#dce6de'}" fill-opacity=".7"/><ellipse cx="90" cy="100" rx="55" ry="12" fill="${filled?'#e9c780':'#e6eee8'}" stroke-width="1"/><path d="M30 30q40-21 110-6l13 3-6 9q-59 17-117-6Z" fill="#edf1e7"/><path d="M43 58h17m-16 20h10m-10 20h17m-16 20h10m-9 20h17" stroke-width="2"/><text x="95" y="161" font-family="Manrope,sans-serif" font-size="22" text-anchor="middle" stroke="none" fill="#3a5059">${label}</text></g></svg>`;},
 ph(value='—',dipped=false,rinsing=false){return `<svg viewBox="0 0 640 430" class="ph-art" aria-hidden="true"><ellipse cx="315" cy="391" rx="254" ry="20" fill="#34485116"/><g stroke="#3d535f" stroke-width="2" stroke-linejoin="round"><path d="m50 240 210-22 43 115-16 43-226 9-27-39Z" fill="#94a8ad"/><path d="m50 240 210-22 43 115-242 14Z" fill="#ecebdd"/><path d="m71 254 159-15 27 75-174 13Z" fill="#385363"/><path d="m82 264 139-13 20 53-149 12Z" fill="#d8e6dd"/><text class="meter-reading" x="165" y="293" font-family="Manrope,sans-serif" font-size="32" font-weight="700" text-anchor="middle" stroke="none" fill="#2a4552">${value}</text><circle cx="119" cy="339" r="9" fill="#be4b43"/><path d="M119 334v5m-4-3a6 6 0 1 0 9 0" fill="none" stroke="#fff3dc" stroke-width="1"/><text x="196" y="294" font-size="12" fill="#59707b" stroke="none">pH</text><path d="m80 363 60-2m-59 9 60-2m-58 9 60-2" stroke="#526c77" stroke-width="1.5"/><path d="M329 370h106l17 14H312Z" fill="#849fa9"/><path d="M376 371V59" stroke-width="12"/><path d="M374 92h141" stroke-width="9"/><path d="M147 238V108q0-72 100-72h217q34 0 34 40v70" fill="none" stroke="#40525a" stroke-width="5"/><path d="M443 240h120l-6 130q-54 23-109 0Z" fill="#e8eee6" fill-opacity=".8"/><path d="M446 292q57 18 113 0l-2 78q-54 23-109 0Z" fill="${rinsing?'#c3dce0':'#ddb469'}" fill-opacity="${rinsing?'.25':'.7'}"/><ellipse cx="503" cy="240" rx="60" ry="15" fill="#eaf0e5" fill-opacity=".7"/>
 ${rinsing?'<g class="rinse-wash"><path d="M562 172h39v76q-20 9-39 0Z" fill="#dce7df"/><path d="M571 157h23v17h-23Z" fill="#b94d42"/><path d="M582 157v-36q0-10-13-10h-28l-22 17" fill="none" stroke-width="5"/></g><path class="rinse-stream" d="M519 128Q499 172 499 240" fill="none" stroke="#78b8ca" stroke-width="4" stroke-dasharray="7 6" opacity="0"/>':''}<g class="electrode ${dipped?'dipped':''}"><rect x="488" y="110" width="22" height="93" rx="5" fill="#4c6e7c"/><path d="M492 203h14v78q-7 12-14 0Z" fill="#c6dadd"/><circle cx="499" cy="280" r="5" fill="#8faab1"/></g></g></svg>`;},
 cloth(){return `<svg viewBox="0 0 150 100" aria-hidden="true"><path d="m15 28 94-15 27 62-98 12Z" fill="#e6e8d7" stroke="#4a6068" stroke-width="1.7"/><path d="m30 36 77-10m-70 24 77-10M42 64l77-10" stroke="#b7c4bc" stroke-width="2"/></svg>`;},
 icon(name){const p={back:'m14 5-7 7 7 7M7 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',book:'M4 4h6q2 0 2 2 0-2 2-2h6v16h-6q-2 0-2 2 0-2-2-2H4ZM12 6v16',help:'M9 8a3 3 0 1 1 4 3c-1 1-1 2-1 3m0 3v1',pause:'M8 5v14M16 5v14',sound:'m11 4-6 5H2v6h3l6 5Zm5 4q6 4 0 8',close:'m6 6 12 12M6 18 18 6',reset:'M4 10a8 8 0 1 1 1 7M4 3v7h7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[name]||p.help}"/></svg>`;}
};
